package es.planidroid.app.data
import android.app.*
import android.content.Context
import android.content.Intent
import androidx.work.*
import es.planidroid.app.MainActivity
import es.planidroid.app.domain.*
import es.planidroid.app.sync.Cloud
import java.time.*
import java.util.concurrent.TimeUnit
object NotificationPrefs {
    private fun store(ctx:Context,uid:String)=ctx.getSharedPreferences("notify-$uid",Context.MODE_PRIVATE)
    fun sessions(ctx:Context,uid:String)=store(ctx,uid).getBoolean("sessions",true)
    fun lead(ctx:Context,uid:String)=store(ctx,uid).getInt("lead",10)
    fun daily(ctx:Context,uid:String)=store(ctx,uid).getBoolean("daily",false)
    fun quietStart(ctx:Context,uid:String)=store(ctx,uid).getString("quietStart","").orEmpty()
    fun quietEnd(ctx:Context,uid:String)=store(ctx,uid).getString("quietEnd","").orEmpty()
    fun muted(ctx:Context,uid:String):Boolean{val start=quietStart(ctx,uid);val end=quietEnd(ctx,uid);if(start.isBlank()||end.isBlank())return false;val now=LocalTime.now();val a=LocalTime.parse(start);val b=LocalTime.parse(end);return if(a<=b)now>=a&&now<b else now>=a||now<b}
    fun set(ctx:Context,uid:String,sessions:Boolean,lead:Int,daily:Boolean,quietStart:String,quietEnd:String){require(lead in 0..1440);require((quietStart.isBlank()&&quietEnd.isBlank())||(quietStart.isNotBlank()&&quietEnd.isNotBlank()&&LocalTime.parse(quietStart)!=LocalTime.parse(quietEnd)));store(ctx,uid).edit().putBoolean("sessions",sessions).putInt("lead",lead).putBoolean("daily",daily).putString("quietStart",quietStart).putString("quietEnd",quietEnd).apply();val wm=WorkManager.getInstance(ctx);if(daily){val now=ZonedDateTime.now();var next=now.toLocalDate().atTime(8,0).atZone(now.zone);if(next<=now)next=next.plusDays(1);val delay=Duration.between(now,next).toMillis();val req=PeriodicWorkRequestBuilder<DailySummaryWorker>(24,TimeUnit.HOURS).setInitialDelay(delay,TimeUnit.MILLISECONDS).setInputData(workDataOf("scope" to uid)).build();wm.enqueueUniquePeriodicWork("daily-$uid",ExistingPeriodicWorkPolicy.UPDATE,req)}else wm.cancelUniqueWork("daily-$uid")}
}
object SessionReminders {
    fun schedule(ctx:Context,uid:String,s:Session){val wm=WorkManager.getInstance(ctx);val key="session-$uid-${s.id}";val due=s.start-NotificationPrefs.lead(ctx,uid)*60000L;if(!NotificationPrefs.sessions(ctx,uid)||s.isBreak||s.done||s.start<=System.currentTimeMillis()){wm.cancelUniqueWork(key);return};val req=OneTimeWorkRequestBuilder<SessionReminderWorker>().setInitialDelay((due-System.currentTimeMillis()).coerceAtLeast(0),TimeUnit.MILLISECONDS).setInputData(workDataOf("scope" to uid,"id" to s.id,"start" to s.start)).build();wm.enqueueUniqueWork(key,ExistingWorkPolicy.REPLACE,req)}
    fun cancel(ctx:Context,uid:String,id:String)=WorkManager.getInstance(ctx).cancelUniqueWork("session-$uid-$id")
    suspend fun refresh(ctx:Context,uid:String){PlanidroidDb.get(ctx).records().all(uid).filter{it.kind==Kind.SESSION.name}.forEach{if(it.deleted)cancel(ctx,uid,it.id)else schedule(ctx,uid,decode<Session>(it.payload))}}
    fun notify(ctx:Context,channel:String,title:String,text:String,id:Int){val manager=ctx.getSystemService(NotificationManager::class.java);manager.createNotificationChannel(NotificationChannel(channel,if(channel=="daily")"Resumen diario" else "Sesiones",NotificationManager.IMPORTANCE_DEFAULT));val pending=PendingIntent.getActivity(ctx,0,Intent(ctx,MainActivity::class.java),PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT);if(manager.areNotificationsEnabled())runCatching{manager.notify(id,Notification.Builder(ctx,channel).setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle(title).setContentText(text).setContentIntent(pending).setAutoCancel(true).build())}}
}
class SessionReminderWorker(ctx:Context,p:WorkerParameters):CoroutineWorker(ctx,p){override suspend fun doWork():Result{val uid=inputData.getString("scope")?:return Result.failure();val id=inputData.getString("id")?:return Result.failure();if((Cloud.auth(applicationContext)?.currentUser?.uid?:"local")!=uid||!NotificationPrefs.sessions(applicationContext,uid)||NotificationPrefs.muted(applicationContext,uid))return Result.success();val dao=PlanidroidDb.get(applicationContext).records();val s=dao.get(uid,id)?.takeUnless{it.deleted}?.let{decode<Session>(it.payload)}?:return Result.success();if(s.isBreak||s.done||s.start!=inputData.getLong("start",-1)||s.end<=System.currentTimeMillis())return Result.success();val t=dao.get(uid,s.taskId)?.takeUnless{it.deleted}?.let{decode<Task>(it.payload)}?:return Result.success();if(t.status in listOf(Status.DONE,Status.ARCHIVED))return Result.success();SessionReminders.notify(applicationContext,"sessions",t.title,"Sesión a las ${Instant.ofEpochMilli(s.start).atZone(ZoneId.systemDefault()).toLocalTime().toString().take(5)}",id.hashCode());return Result.success()}}
class DailySummaryWorker(ctx:Context,p:WorkerParameters):CoroutineWorker(ctx,p){override suspend fun doWork():Result{val uid=inputData.getString("scope")?:return Result.failure();if((Cloud.auth(applicationContext)?.currentUser?.uid?:"local")!=uid||!NotificationPrefs.daily(applicationContext,uid)||NotificationPrefs.muted(applicationContext,uid))return Result.success();val rows=PlanidroidDb.get(applicationContext).records().all(uid).filterNot{it.deleted};val tasks=rows.filter{it.kind==Kind.TASK.name}.map{decode<Task>(it.payload)}.filter{it.status !in listOf(Status.DONE,Status.ARCHIVED)};val sessions=rows.filter{it.kind==Kind.SESSION.name}.map{decode<Session>(it.payload)}.filter{!it.isBreak&&!it.done&&Instant.ofEpochMilli(it.start).atZone(ZoneId.systemDefault()).toLocalDate()==LocalDate.now()};SessionReminders.notify(applicationContext,"daily","Tu día en Planidroid","${tasks.size} pendientes · ${sessions.size} sesiones para hoy",uid.hashCode());return Result.success()}}
